{* Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/topic-chips.json
    A centered row of topic pills: links where a topic has an address, else buttons. tone inverse: on a dark band with an icon per topic; default: outlined.
    Props (p): topics, tone. *}
{var $v_topics = ($p['topics'] ?? null)}
{var $v_tone = ($p['tone'] ?? 'default')}
{capture $c_3}
  {foreach og_l($v_topics) as $v_topic}
    {if og_t(og_eq($v_tone, 'inverse'))}
      {capture $c_1}
        {if og_t(og_get($v_topic, ['icon']))}
          {=og_include('icons/LucideIcon.latte', ['name' => og_s(og_get($v_topic, ['icon'])), 'size' => 16])|noescape}
        {/if}
        {=og_text(og_get($v_topic, ['name']))}
      {/capture}
      {=og_include('compose/Button.latte', ['href' => og_url(og_s(og_get($v_topic, ['href']))), 'variant' => 'ghost', 'size' => 'sm', 'class' => 'gap-2 text-background inset-ring-background/30 hover:bg-background/10', 'children' => (string) $c_1])|noescape}
    {else}
      {capture $c_2}
        {=og_text(og_get($v_topic, ['name']))}
      {/capture}
      {=og_include('compose/Button.latte', ['href' => og_url(og_s(og_get($v_topic, ['href']))), 'variant' => 'outline', 'size' => 'sm', 'children' => (string) $c_2])|noescape}
    {/if}
  {/foreach}
{/capture}
{=og_include('compose/Group.latte', ['gap' => '2', 'align' => 'center', 'justify' => 'center', 'class' => 'flex-wrap', 'attrs' => og_attrs(['data-slot', 'hero-topics']), 'children' => (string) $c_3])|noescape}
